// Behavioral Health Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test
// plan, slightly harder than the sample items: brain-behavior links, diagnostic features and
// SAMHSA prevention and recovery concepts.
import {q, mix} from './q.js';
const PSY='Cacioppo & Freberg, Discovering Psychology', SAM='SAMHSA', NAMI='NAMI';
const MIND='The Mind', DIS='Psychology and Behavioral Health Disorders, Treatments, Therapies & Services', SUB='Prevention, Identification, Recovery, and Management of Substance Abuse and Mental Illness', WELL='Wellness, Stress, Coping', WORK='Workforce/Careers and Laws, Regulations and Guidelines', HIST='History and Health Systems Integration';

export default {
 id:'behavioral-health-1',
 event:'Behavioral Health',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Cacioppo & Freberg’s Discovering Psychology, SAMHSA and NAMI',
 plan:[{area:MIND,weight:25},{area:DIS,weight:25},{area:SUB,weight:25},{area:WELL,weight:15},{area:WORK,weight:5},{area:HIST,weight:5}],
 questions:mix([
  q(MIND,'Damage to which brain structure most impairs the ability to form new long-term memories of facts and events?','Hippocampus',['Cerebellum','Amygdala','Occipital lobe'],'B','The hippocampus consolidates new explicit (declarative) memories. The cerebellum handles motor learning, and the amygdala processes emotion, especially fear.',PSY),
  q(MIND,'Which structure plays a central role in detecting threats and producing fear responses?','Amygdala',['Hippocampus','Thalamus','Corpus callosum'],'D','The amygdala, part of the limbic system, evaluates emotional significance, especially threat, and triggers fear responses.',PSY),
  q(MIND,'A student’s heart races and pupils dilate before a presentation. Which division of the nervous system is responsible?','Sympathetic nervous system',['Parasympathetic nervous system','Somatic nervous system','Central nervous system only'],'A','The sympathetic division of the autonomic nervous system produces the fight-or-flight response. The parasympathetic division calms the body (“rest and digest”).',PSY),
  q(MIND,'What is transduction in sensation?','Turning stimuli into neural signals',['Interpreting sensory information','Ignoring unchanging stimuli','Combining senses into one experience'],'C','Sensory receptors transduce light, sound or pressure into nerve impulses. Interpretation of those signals is perception, and reduced response to an unchanging stimulus is adaptation.',PSY),
  q(MIND,'The smallest change in a stimulus that a person can detect half the time is called the:','Difference threshold',['Absolute threshold','Signal threshold','Sensory adaptation point'],'B','The difference threshold, or just-noticeable difference, follows Weber’s law: it is a constant proportion of the original stimulus. The absolute threshold is the weakest stimulus detectable.',PSY),
  q(MIND,'A person sees a circle with small gaps as a complete circle. Which Gestalt principle explains this?','Closure',['Proximity','Similarity','Continuity'],'D','Closure is the tendency to fill in gaps to perceive complete figures. Proximity groups nearby items, and similarity groups items that look alike.',PSY),
  q(MIND,'Which statement describes REM sleep?','Vivid dreams with most muscles paralyzed',['Brain waves are slowest and deepest','It occurs only in the first hour of sleep','The body is most active and moves the most'],'A','During REM sleep, brain activity resembles wakefulness and dreams are vivid, but most voluntary muscles are temporarily paralyzed. Slow-wave sleep has the slowest brain waves.',PSY),
  q(MIND,'Which brain structure acts as the body’s master clock for circadian rhythms?','Suprachiasmatic nucleus',['Pineal gland of the midbrain','Pons of the brainstem','Frontal lobe of the cortex'],'C','The suprachiasmatic nucleus receives light information from the eyes and signals the pineal gland to adjust melatonin release.',PSY),
  q(MIND,'A student practices piano because she enjoys it, not for rewards. What type of motivation is this?','Intrinsic motivation',['Extrinsic motivation','Drive reduction','Incentive motivation'],'B','Intrinsic motivation comes from inner satisfaction. Extrinsic motivation comes from outside rewards or pressures, such as grades or money.',PSY),
  q(MIND,'According to the James-Lange theory, what happens when a person meets a bear?','The body reacts first, and the emotion follows',['The emotion and body reaction happen together','The person thinks first, then feels emotion','The emotion causes the body reaction'],'D','James-Lange proposed that emotion results from perceiving bodily changes: “I tremble, so I am afraid.” Cannon-Bard proposed they occur at the same time.',PSY),
  q(MIND,'In Pavlov’s experiments, the bell that made dogs salivate after being paired with food was the:','Conditioned stimulus',['Unconditioned stimulus','Unconditioned response','Neutral response'],'A','The bell was originally neutral; after pairing with food (the unconditioned stimulus), it became a conditioned stimulus that triggered salivation (the conditioned response).',PSY),
  q(MIND,'A driver buckles the seatbelt to stop the car’s annoying beeping. Which learning process increases this behavior?','Negative reinforcement',['Positive punishment','Negative punishment','Extinction'],'C','Negative reinforcement removes an unpleasant stimulus, which makes the behavior more likely. Punishment makes a behavior less likely.',PSY),
  q(MIND,'After a concussion, a patient cannot remember events from the days before the injury but can form new memories. What is this called?','Retrograde amnesia',['Anterograde amnesia','Infantile amnesia','Source amnesia'],'B','Retrograde amnesia is loss of memories formed before an injury. Anterograde amnesia is inability to form new memories after it.',PSY),
  q(DIS,'Which two core features define autism spectrum disorder?','Social communication deficits and repetitive behaviors',['Hallucinations, delusions and disorganized speech','Inattention and hyperactivity with no other signs','Mood swings and impulsivity'],'D','ASD involves persistent difficulties in social communication and interaction plus restricted, repetitive patterns of behavior or interests, present from early childhood.',NAMI),
  q(DIS,'Why are stimulant medications such as methylphenidate used to treat ADHD?','They boost dopamine and norepinephrine',['They sedate the child so they move less','They block serotonin reuptake','They cure the disorder after a few months'],'A','Stimulants boost dopamine and norepinephrine in brain networks that control attention and impulses, improving focus. They manage symptoms but do not cure ADHD.',NAMI),
  q(DIS,'Many antipsychotic medications reduce hallucinations by blocking which neurotransmitter’s receptors?','Dopamine',['Serotonin only','GABA','Acetylcholine'],'C','The dopamine hypothesis links positive symptoms of schizophrenia to excess dopamine activity. First-generation antipsychotics block dopamine D2 receptors.',PSY),
  q(DIS,'Which medication is a classic mood stabilizer for bipolar disorder and requires blood level monitoring?','Lithium',['Sertraline','Lorazepam','Methylphenidate'],'B','Lithium reduces manic and depressive episodes but has a narrow therapeutic range, so blood levels and kidney and thyroid function are monitored.',NAMI),
  q(DIS,'How long must symptoms last for a diagnosis of major depressive disorder?','At least 2 weeks',['At least 2 days','At least 6 months','At least 2 years'],'D','Major depression requires depressed mood or loss of interest plus other symptoms most of the day, nearly every day, for at least 2 weeks.',NAMI),
  q(DIS,'A person has repeated, sudden episodes of intense fear with chest pain and shortness of breath, and now avoids leaving home. What is most likely?','Panic disorder',['Generalized anxiety disorder','Specific phobia','Social anxiety disorder'],'A','Panic disorder involves recurrent, unexpected panic attacks and worry about future attacks; it can lead to agoraphobia.',NAMI),
  q(DIS,'Which therapy is most effective for obsessive-compulsive disorder?','Exposure and response prevention',['Electroconvulsive therapy','Freudian psychoanalysis','Hypnosis and suggestion'],'C','Exposure and response prevention, a form of CBT, has patients face triggers while resisting compulsions, which weakens the cycle of anxiety and ritual. SSRIs are also used.',NAMI),
  q(DIS,'For a PTSD diagnosis in adults, symptoms such as flashbacks and avoidance must last longer than:','1 month',['3 days','6 months','1 year'],'B','Symptoms lasting 3 days to 1 month after trauma may be acute stress disorder. PTSD symptoms last more than 1 month.',NAMI),
  q(DIS,'Which therapy was developed specifically for borderline personality disorder?','Dialectical behavior therapy',['Exposure therapy','Applied behavior analysis','Light therapy'],'D','DBT teaches mindfulness, distress tolerance, emotion regulation and interpersonal skills to address the intense emotions and unstable relationships of BPD.',NAMI),
  q(DIS,'Which feature defines dissociative identity disorder?','Two or more distinct personality states',['Hearing voices that others cannot hear','Extreme mood swings between mania and depression','Fear of gaining weight'],'A','DID involves two or more distinct identities with gaps in memory. It is often linked to severe childhood trauma and is different from schizophrenia.',NAMI),
  q(DIS,'Which mental health condition has one of the highest death rates?','Anorexia nervosa',['Specific phobia','Adjustment disorder','Seasonal affective disorder'],'C','Anorexia has one of the highest mortality rates of any mental illness because of starvation’s effects on the heart and other organs, and because of suicide.',NAMI),
  q(DIS,'What is the main focus of cognitive behavioral therapy?','Changing unhelpful thoughts and behaviors',['Exploring unconscious childhood conflicts','Interpreting dreams','Replacing medication entirely'],'B','CBT helps patients identify and challenge distorted thinking and build healthier behaviors. It is effective for depression, anxiety and many other conditions.',PSY),
  q(SUB,'How does SAMHSA define recovery?','A process of change toward one’s full potential',['Complete abstinence for at least five years','Finishing a 30-day treatment program','The absence of all symptoms of illness'],'D','SAMHSA defines recovery as a process of change through which people improve their health and wellness, live self-directed lives and strive to reach their full potential.',SAM),
  q(SUB,'Which are SAMHSA’s four major dimensions that support recovery?','Health, home, purpose and community',['Diet, exercise, sleep and work','Family, faith, school and money','Medication, therapy, rest and diet'],'A','A stable home, a sense of purpose, supportive community relationships and good health all support recovery.',SAM),
  q(SUB,'A person has both an alcohol use disorder and depression. What is this called?','Co-occurring disorders',['Comorbid relapse syndrome','Dual tolerance disorder','Cross-addiction'],'C','Co-occurring disorders are a mental health condition and a substance use disorder at the same time. Integrated treatment of both works best.',SAM),
  q(SUB,'What does SBIRT stand for?','Screening, Brief Intervention, and Referral to Treatment',['Substance-Based Inpatient Recovery Treatment','Support, Behavior, Intervention, Recovery, Therapy','Screening for Behavioral Illness and Risk Trends'],'B','SBIRT is an evidence-based approach for identifying risky substance use, especially in primary care, and connecting people to the right level of care.',SAM),
  q(SUB,'Which medications are FDA-approved to treat opioid use disorder?','Buprenorphine, methadone and naltrexone',['Lithium, sertraline and lorazepam','Naloxone, aspirin and acetaminophen','Methylphenidate, clonidine and insulin'],'D','Medications for opioid use disorder reduce cravings and withdrawal and lower overdose deaths. Naloxone reverses an overdose but does not treat the disorder.',SAM),
  q(SUB,'Distributing naloxone kits to people who use opioids is an example of:','Harm reduction',['Primary prevention','Detoxification','Enabling'],'A','Harm reduction meets people where they are to reduce the dangers of drug use, such as overdose deaths and infections, without requiring abstinence first.',SAM),
  q(SUB,'Which is a protective factor against youth substance use?','Strong bonds with family',['Early aggressive behavior','Easy access to drugs','Peer substance use'],'C','Protective factors, such as strong family bonds, parental monitoring and school engagement, lower risk. The other choices are risk factors.',SAM),
  q(SUB,'A prevention program targets children of parents with addiction. Which level of prevention is this?','Selective prevention',['Universal prevention','Indicated prevention','Tertiary treatment'],'B','Universal prevention reaches everyone; selective prevention targets groups at higher risk; indicated prevention targets individuals already showing early signs.',SAM),
  q(SUB,'Which two findings indicate physical dependence on a substance?','Tolerance and withdrawal',['Euphoria and relaxation','Cravings and relapse','Denial and anger'],'D','Tolerance (needing more for the same effect) and withdrawal (symptoms when stopping) show physical dependence. Addiction also involves compulsive use despite harm.',SAM),
  q(SUB,'Why should withdrawal from heavy, long-term alcohol use be medically supervised?','It can cause seizures and delirium tremens',['It is always painless','It never lasts more than a few hours','It causes only mild headaches'],'A','Severe alcohol withdrawal can cause seizures and delirium tremens, which can be fatal. Benzodiazepines are often used to manage it safely.',SAM),
  q(SUB,'Why is illicit fentanyl driving so many overdose deaths?','It is far more potent than heroin',['It cannot be reversed by naloxone','It is only taken by injection','It has no effect on breathing'],'C','Fentanyl is about 50 times stronger than heroin, so tiny amounts, often hidden in other drugs, can stop breathing. Naloxone works but more than one dose may be needed.',SAM),
  q(SUB,'Which number connects people in the United States to the Suicide & Crisis Lifeline?','988',['911','411','211'],'B','Dialing or texting 988 connects to trained crisis counselors 24/7 for mental health, substance use and suicidal crises. 211 connects people to community resources.',SAM),
  q(SUB,'Which phrase follows person-first language and helps reduce stigma?','A person with a substance use disorder',['A drug addict who uses','A substance abuser','A habitual drug user'],'D','Person-first language describes the person before the condition, which reduces stigma and encourages people to seek treatment.',SAM),
  q(WELL,'During stress, the HPA axis causes the adrenal glands to release which hormone?','Cortisol',['Insulin','Melatonin','Oxytocin'],'A','The hypothalamus signals the pituitary, which signals the adrenal cortex to release cortisol. Chronic high cortisol can weaken immunity and affect mood.',PSY),
  q(WELL,'In Selye’s general adaptation syndrome, what is the correct order of stages?','Alarm, resistance, exhaustion',['Resistance, alarm, exhaustion','Exhaustion, alarm, resistance','Alarm, exhaustion, recovery'],'C','The body first mobilizes (alarm), then adapts to ongoing stress (resistance), and finally becomes depleted if stress continues (exhaustion), increasing illness risk.',PSY),
  q(WELL,'A student facing a failing grade makes a study schedule and meets the teacher. Which coping style is this?','Problem-focused coping',['Emotion-focused coping','Avoidant coping','Defensive coping'],'B','Problem-focused coping changes the stressful situation itself. Emotion-focused coping manages feelings about a situation that may not be changeable.',PSY),
  q(WELL,'Stress that motivates a person and has positive effects, such as excitement before a game, is called:','Eustress',['Distress','Burnout','Hypervigilance'],'D','Eustress is positive stress that can improve performance. Distress is harmful stress that overwhelms coping.',PSY),
  q(WELL,'Which is one of SAMHSA’s eight dimensions of wellness?','Financial',['Genetic','Political','Athletic'],'A','SAMHSA’s eight dimensions are emotional, environmental, financial, intellectual, occupational, physical, social and spiritual.',SAM),
  q(WELL,'What is mindfulness?','Nonjudgmental attention to the present',['Suppressing unwanted thoughts completely','Planning every part of the future','Analyzing past mistakes in detail'],'C','Mindfulness means noticing thoughts, feelings and sensations as they happen, without judging them. Regular practice can reduce stress, anxiety and depression.',PSY),
  q(WELL,'What does resilience mean in behavioral health?','Adapting and recovering after adversity',['Never feeling stress or sadness','Avoiding all difficult situations','Relying only on medication'],'B','Resilience is the ability to bounce back from hardship. It can be strengthened through supportive relationships, coping skills and a sense of purpose.',SAM),
  q(WORK,'Which federal law requires most health plans to cover mental health and substance use care on terms no more restrictive than medical care?','The Mental Health Parity Act',['The Controlled Substances Act','The Americans with Disabilities Act','The Family and Medical Leave Act of 1993'],'D','The 2008 parity law means copays, visit limits and prior authorization rules for behavioral health cannot be stricter than those for medical and surgical care.',SAM),
  q(WORK,'What makes a peer support specialist different from other behavioral health workers?','They draw on their own lived experience',['They prescribe psychiatric medications','They must hold a medical degree','They work only in emergency rooms'],'A','Peer specialists have personal experience with mental illness or substance use and recovery. They offer hope, mentoring and help navigating services.',SAM),
  q(WORK,'Which federal regulation gives special confidentiality protection to records from substance use disorder treatment programs?','42 CFR Part 2',['Title IX','The Stark Law','OSHA 1910'],'C','42 CFR Part 2 limits the sharing of substance use disorder treatment records without patient consent, beyond the general protections of HIPAA.',SAM),
  q(HIST,'Beginning in the 1960s, many patients were moved from large state psychiatric hospitals to community-based care. What is this shift called?','Deinstitutionalization',['Service integration','Managed care','Moral treatment reform'],'B','New medications and the Community Mental Health Act of 1963 drove deinstitutionalization. Too few community services left many people without adequate care.',PSY),
  q(HIST,'What is the main goal of integrating behavioral health into primary care?','Treating mental and physical health together in one setting',['Replacing psychiatrists with primary care doctors','Moving all mental health care into hospitals','Separating mental health records from medical records'],'D','Integrated care places behavioral health providers in primary care settings, improving access, early detection and treatment of the whole person.',SAM)
 ],53)
};
